BEGIN;
ALTER TABLE integration_jobs DROP CONSTRAINT integration_jobs_kind_check;
ALTER TABLE integration_jobs ADD CONSTRAINT integration_jobs_kind_check CHECK(kind IN('file','provider_sync','provider_update','legal_review','provider_calendar'));
ALTER TABLE provider_sync_bindings ADD COLUMN remote_recurrence text NOT NULL DEFAULT '';
ALTER TABLE provider_sync_bindings ADD COLUMN remote_court_rule boolean NOT NULL DEFAULT false;
CREATE TABLE provider_webhooks(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,connection_id uuid NOT NULL,principal_id text NOT NULL,model text NOT NULL CHECK(model IN('matter','calendar_entry')),callback_sha256 text NOT NULL,remote_id text,handshake_id text,encrypted_secret bytea,state text NOT NULL DEFAULT 'creating' CHECK(state IN('creating','pending','active','uncertain','disabled')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,connection_id)REFERENCES provider_connections(tenant_id,id));
CREATE TABLE provider_webhook_receipts(tenant_id uuid NOT NULL,subscription_id uuid NOT NULL REFERENCES provider_webhooks(id),body_sha256 text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(subscription_id,body_sha256));
CREATE TABLE provider_sync_signals(tenant_id uuid NOT NULL,connection_id uuid PRIMARY KEY,principal_id text NOT NULL,generation bigint NOT NULL DEFAULT 1,consumed bigint NOT NULL DEFAULT 0,lease_token uuid,lease_expires_at timestamptz,FOREIGN KEY(tenant_id,connection_id)REFERENCES provider_connections(tenant_id,id));
CREATE TABLE provider_calendar_operations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,connection_id uuid NOT NULL,calendar_id uuid NOT NULL,matter_id uuid NOT NULL,entry_id uuid,operation text NOT NULL CHECK(operation IN('create','update')),payload jsonb NOT NULL,artifact_sha256 text NOT NULL,expected_revision bigint NOT NULL,expected_etag text NOT NULL,proposed_by text NOT NULL,reviewed_by text,remote_id text,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','approved','rejected','inflight','completed','conflict','uncertain')),FOREIGN KEY(tenant_id,calendar_id)REFERENCES calendars(tenant_id,id),FOREIGN KEY(tenant_id,matter_id)REFERENCES matters(tenant_id,id),FOREIGN KEY(tenant_id,connection_id)REFERENCES provider_connections(tenant_id,id));
CREATE TABLE knowledge_libraries(tenant_id uuid NOT NULL,matter_id uuid NOT NULL,name text NOT NULL,created_by text NOT NULL,PRIMARY KEY(tenant_id,matter_id),FOREIGN KEY(tenant_id,matter_id)REFERENCES matters(tenant_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['provider_webhooks','provider_webhook_receipts','provider_sync_signals','provider_calendar_operations','knowledge_libraries']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_guard ON %I USING(tenant_id::text=current_setting(''app.tenant_id'',true)) WITH CHECK(tenant_id::text=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
GRANT SELECT,INSERT ON provider_webhooks,provider_webhook_receipts,provider_sync_signals,provider_calendar_operations TO lawpilot_integration;
GRANT UPDATE(remote_id,handshake_id,encrypted_secret,state)ON provider_webhooks TO lawpilot_integration;
GRANT UPDATE(generation,principal_id)ON provider_sync_signals TO lawpilot_integration;
GRANT UPDATE(state,reviewed_by,remote_id)ON provider_calendar_operations TO lawpilot_integration;
GRANT SELECT ON provider_sync_bindings TO lawpilot_calendar;
GRANT SELECT ON calendars,calendar_entries,calendar_grants,provider_sync_bindings TO lawpilot_context;
GRANT SELECT,INSERT ON knowledge_libraries TO lawpilot_context;
CREATE FUNCTION claim_provider_sync_signals()RETURNS TABLE(tenant_id uuid,connection_id uuid,principal_id text,generation bigint,lease_token uuid)LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$WITH picked AS(SELECT s.connection_id FROM public.provider_sync_signals s WHERE s.generation>s.consumed AND(s.lease_expires_at IS NULL OR s.lease_expires_at<now())ORDER BY s.connection_id FOR UPDATE SKIP LOCKED LIMIT 20),updated AS(UPDATE public.provider_sync_signals s SET lease_token=gen_random_uuid(),lease_expires_at=now()+interval '1 minute' FROM picked p WHERE p.connection_id=s.connection_id RETURNING s.*)SELECT tenant_id,connection_id,principal_id,generation,lease_token FROM updated$$;
CREATE FUNCTION settle_provider_sync_signal(p_id uuid,p_token uuid,p_generation bigint,p_ok boolean)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE n integer;BEGIN UPDATE public.provider_sync_signals SET consumed=CASE WHEN p_ok THEN greatest(consumed,p_generation)ELSE consumed END,lease_token=NULL,lease_expires_at=CASE WHEN p_ok THEN NULL ELSE now()+interval '1 minute' END WHERE connection_id=p_id AND lease_token=p_token AND lease_expires_at>now();GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
-- The callback uses an unguessable route capability before a tenant transaction can start.
CREATE FUNCTION locate_provider_webhook(p_id uuid)RETURNS TABLE(tenant_id uuid,callback_sha256 text)LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$SELECT tenant_id,callback_sha256 FROM public.provider_webhooks WHERE id=p_id AND state<>'disabled'$$;
REVOKE ALL ON FUNCTION claim_provider_sync_signals(),settle_provider_sync_signal(uuid,uuid,bigint,boolean),locate_provider_webhook(uuid)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION claim_provider_sync_signals(),settle_provider_sync_signal(uuid,uuid,bigint,boolean),locate_provider_webhook(uuid)TO lawpilot_integration;
COMMIT;
